create extension if not exists pgcrypto;
create type episode_status as enum ('collecting','researching','scripting','synthesizing','mixing','needs_review','approved','publishing','published','failed','archived');
create table feeds(id uuid primary key default gen_random_uuid(),name text not null,url text not null unique,category text not null default 'عام',priority smallint not null default 50 check(priority between 0 and 100),active boolean not null default true,last_fetched_at timestamptz,last_success_at timestamptz,last_error text,created_at timestamptz not null default now());
create table feed_items(id uuid primary key default gen_random_uuid(),feed_id uuid not null references feeds on delete cascade,external_id text not null,title text not null,url text not null,published_at timestamptz not null,raw jsonb not null default '{}',content_hash text not null unique,created_at timestamptz not null default now(),unique(feed_id,external_id));
create table articles(id uuid primary key default gen_random_uuid(),feed_item_id uuid not null references feed_items on delete cascade,extracted_text text,extraction_status text not null default 'pending',sensitive boolean not null default false,created_at timestamptz not null default now());
create table story_clusters(id uuid primary key default gen_random_uuid(),title text not null,summary text,score numeric not null default 0,sensitive boolean not null default false,eligible boolean not null default false,created_at timestamptz not null default now());
create table story_sources(story_id uuid references story_clusters on delete cascade,article_id uuid references articles on delete cascade,primary key(story_id,article_id));
create table episodes(id uuid primary key default gen_random_uuid(),episode_number bigint generated always as identity,title text,description text,summary text,telegram_caption text,status episode_status not null default 'collecting',target_seconds integer not null default 600 check(target_seconds between 480 and 720),estimated_seconds integer,approved_at timestamptz,approved_by uuid references auth.users,audio_checksum text,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table episode_stories(episode_id uuid references episodes on delete cascade,story_id uuid references story_clusters,position smallint not null,enabled boolean not null default true,primary key(episode_id,story_id));
create table scripts(id uuid primary key default gen_random_uuid(),episode_id uuid not null references episodes on delete cascade,version integer not null,content jsonb not null,approved_snapshot boolean not null default false,created_at timestamptz not null default now(),unique(episode_id,version));
create table script_segments(id uuid primary key default gen_random_uuid(),script_id uuid not null references scripts on delete cascade,story_id uuid references story_clusters,speaker text not null check(speaker in ('host_a','host_b')),position integer not null,text text not null,source_urls jsonb not null,pronunciation_notes jsonb not null default '[]',audio_asset_id uuid,created_at timestamptz not null default now(),unique(script_id,position));
create table audio_assets(id uuid primary key default gen_random_uuid(),episode_id uuid references episodes on delete cascade,kind text not null,storage_key text not null,content_type text not null,duration_seconds numeric,checksum text,provider text,model text,voice_id text,cost_sar numeric,valid boolean not null default true,created_at timestamptz not null default now());
alter table script_segments add constraint segment_audio_fk foreign key(audio_asset_id) references audio_assets(id);
create table music_tracks(id uuid primary key default gen_random_uuid(),name text not null,storage_key text not null,license_type text not null,license_evidence text not null,rights_confirmed boolean not null default false,is_default boolean not null default false,duration_seconds numeric,loudness_lufs numeric,created_at timestamptz not null default now());
create table mix_versions(id uuid primary key default gen_random_uuid(),episode_id uuid not null references episodes on delete cascade,version integer not null,music_track_id uuid references music_tracks,parameters jsonb not null,output_asset_id uuid references audio_assets,created_at timestamptz not null default now(),unique(episode_id,version));
create table pronunciations(id uuid primary key default gen_random_uuid(),written text not null unique,spoken text not null,notes text,created_at timestamptz not null default now());
create table generation_jobs(id uuid primary key default gen_random_uuid(),episode_id uuid references episodes on delete cascade,stage text not null,status text not null default 'queued',attempt integer not null default 0,idempotency_key text not null unique,input jsonb not null default '{}',output jsonb,last_error text,started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now());
create table provider_usage(id uuid primary key default gen_random_uuid(),episode_id uuid references episodes on delete set null,provider text not null,operation text not null,units numeric,cost_sar numeric,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table publish_deliveries(id uuid primary key default gen_random_uuid(),episode_id uuid not null references episodes on delete cascade,channel text not null,status text not null default 'pending',idempotency_key text not null unique,external_id text,public_url text,last_error text,attempts integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table audit_events(id bigint generated always as identity primary key,actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table app_settings(id boolean primary key default true check(id),settings jsonb not null default '{"timezone":"Asia/Riyadh","schedule":"0 6 * * *","publishingPaused":true,"maxStories":8,"dailyBudgetSar":50,"monthlyBudgetSar":1000}',updated_at timestamptz not null default now());
insert into app_settings(id) values(true) on conflict do nothing;
alter table feeds enable row level security; alter table episodes enable row level security; alter table scripts enable row level security; alter table music_tracks enable row level security; alter table audit_events enable row level security;
create policy owner_feeds on feeds for all to authenticated using(auth.jwt()->>'email'=current_setting('app.owner_email',true)) with check(auth.jwt()->>'email'=current_setting('app.owner_email',true));
create policy owner_episodes on episodes for all to authenticated using(auth.jwt()->>'email'=current_setting('app.owner_email',true)) with check(auth.jwt()->>'email'=current_setting('app.owner_email',true));
create policy owner_scripts on scripts for all to authenticated using(auth.jwt()->>'email'=current_setting('app.owner_email',true)) with check(auth.jwt()->>'email'=current_setting('app.owner_email',true));
create policy owner_music on music_tracks for all to authenticated using(auth.jwt()->>'email'=current_setting('app.owner_email',true)) with check(auth.jwt()->>'email'=current_setting('app.owner_email',true));
create policy owner_audit on audit_events for select to authenticated using(auth.jwt()->>'email'=current_setting('app.owner_email',true));
